import json
from ute_common_abstract_core.aliases_registry import aliases_registry
from ute_common_abstract_core.exceptions import UnknownAlias, WrongAlias
from ute_common_abstract_core.network_elem_identification import UeIdentification
from ute_ue.config import loggers as ta_ue_logging
from ute_ue.lteue import LteUe
from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer
from taf.ue.mtk.utils import add_interface_trace
from taf.ue.mtk.datatransfer.iperf_data_transfer import IperfDownLinkDataTransfer, IperfUpLinkDataTransfer
from taf.ue.mtk.exceptions import NoIpError


class MtkUe(LteUe):

    def __init__(self, name, ue_id, ue_pc, configuration):
        """
        :param name:
        :param ue_id:
        :param ue_pc:
        :param configuration:
        """
        super(MtkUe, self).__init__(name, configuration)

        self.prepared = False
        self.ue_pc = ue_pc
        self.ue_id = ue_id
        self.pdns = self._configuration.get("pdns", {})
        self.default_pdn_name = None
        self.current_pdn_name = None
        self.ue_ip = None

        self._create_ue_identification()
        self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(self.logger, {'area': 'UE', 'ue_id': self.ue_id})

    def _create_ue_identification(self):
        ue_identification = self.ue_id
        self.ne_id = UeIdentification(identifiers=[('mtk', ue_identification)],
                                      network_elem_type='UE',
                                      specific_for_tool='mtk')

    def __str__(self):
        return "{}({})".format(self.__class__.__name__, self.name if hasattr(self, "name") else '')

    def __repr__(self):
        return "{}({}, at {})".format(self.__class__.__name__, self.name if hasattr(self, "name") else '',
                                      hex(id(self)))

    @property
    def id(self):
        return self.ue_id

    @property
    def ip(self):
        return self.ue_ip

    def _get_default_pdn_name(self):
        default_pdn_name = self._configuration.get("default_pdn_name", None)

        pdn_num = len(self.pdns)
        if default_pdn_name is None:
            if pdn_num == 1:
                for key in self.pdns.keys():
                    default_pdn_name = key
            else:
                raise ValueError("initialize 'default_pdn_name' when multiple pdn, pdns={}".format(self.pdns))

        return default_pdn_name

    def prepare_ue(self):
        """Call this after constructor. This method may take some time."""
        self.default_pdn_name = self._get_default_pdn_name()
        self.current_pdn_name = self.default_pdn_name
        access_layer_ue_config = {'serial_number': self.ue_id,
                                  'pdn_name': self.default_pdn_name,
                                  'pdns': self.pdns,
                                  'com_port': self._configuration.get("com_port", None),
                                  'edb_file_path': self._configuration.get("edb_file_path", None),
                                  'log_filter': self._configuration.get("log_filter", None),
                                  'imei': self._configuration.get("imei", None),
                                  'imsi': self._configuration.get("imsi", None),
                                  'capabilities': self._configuration.get("capabilities", [])}
        self.logger.info("access layer ue configuration {}".format(access_layer_ue_config))
        self.prepared = self.ue_pc.reserve_ue(ue_id=self.ue_id, ue_config=access_layer_ue_config)
        self.logger.debug("prepare_ue after calling reserve_ue on taf.ue.proxy")
        return self.prepared

    @add_interface_trace
    def shutdown(self):
        return self.ue_pc.release_ue(ue_id=self.ue_id)

    @add_interface_trace
    def register(self, timeout=3, **kwargs):
        return self.ue_pc.register(ue_id=self.ue_id, timeout=timeout, **kwargs)

    @add_interface_trace
    def attach(self, timeout=3, **kwargs):
        """
        Perform attach on UE.

        :param timeout: Time during which UE should finish attach procedure(change attach state and connect to cell)
        :param kwargs: UE specific arguments
        :return: None
        """
        response = self.ue_pc.attach_ue(ue_id=self.ue_id, timeout=timeout, **kwargs)
        self.log_ue_info()
        self.ue_ip = self._get_ue_ip()
        return response

    @add_interface_trace
    def detach(self, timeout=3, **kwargs):
        """
        Perform detach on UE.
        No action if UE is already detached.

        :param timeout: Time during which UE should perform detach
        :param kwargs: UE specific arguments
        :return: None
        """
        return self.ue_pc.detach_ue(ue_id=self.ue_id, timeout=timeout, **kwargs)

    @add_interface_trace
    def log_ue_info(self, info_list=None):
        """
        Logs specified UE information.

        :param info_list: List of information to be logged, None by default,
            - available values (FastMile): ALL, NAME, SERIAL, OS_VERSION, BUILD_VERSION, DEVICE_MODEL, IP, IPS, IMEI
        :return: None
        """
        response = self.get_ue_info(info_list)
        self.logger.info('Response: {}'.format(response))

    def _get_ue_ip(self):
        ue_ips_dict = self.ue_pc.get_ue_info(ue_id=self.ue_id, ue_attributes=['ips'])['ips']
        self.logger.info("Got MediaTek ips: {}".format(ue_ips_dict))
        if len(ue_ips_dict) == 0:
            self.logger.debug("MediaTek didn't get any IP address.")
            return None
        if self.current_pdn_name not in ue_ips_dict.keys():
            self.logger.debug("MediaTek UE didn't get IP address for \"{}\" APN"
                              " - got IP for following APNs: {}".format(self.current_pdn_name, list(ue_ips_dict.keys())))
            return None
        return ue_ips_dict.get(self.current_pdn_name)[0]

    @add_interface_trace
    def get_ue_info(self, info_list=None):
        """
        Get specified UE information.
        :param info_list: info(s) to be returned, None by default and it means 'ALL'.
        :return: string value for single info; dict {'info_name': 'info_value'} for multiple info
        """
        response = self.get_info(info_list)
        self.logger.debug(f"output from get_info: {response}")
        response = list(response.values())[0] if len(response) == 1 else response
        return response

    def get_info(self, info_type, timeout=None):
        """
        Return information about UE
        Example:
            ue.get_info('serial')
                --> {'serial': '0123456789ABCDEF'}
            ue.get_info(['serial', 'ips'])
                --> {'serial': '0123456789ABCDEF', 'ips': ['172.180.252.185']}
            ue.get_info('all')
                --> {dict with all available ue information}
        Note: `info_type` is case-insensitive

        Available `info_type` values are:
            'NAME' - `device` UE info from `adb devices -l` command
            'SERIAL' - UE serial number
            'OS_VERSION' - MediaTek UE version(e.g. Petrus, Figeac, Dujac)
            'BUILD_VERSION' - UE firmware version, equivalent of `adb shell getprop ro.build.id`
            'DEVICE_MODEL' - UE device model
            'IMSI' - IMSI number on UE
            'IMEI' - IMEI number on UE
            'IP' - UE ip info at some point
            'IPS' - returns a dict of apn_name and its ip addresses both v4 and v6;
                    TODO: implement getting ipV6 address
                    e.g. {"dxdata1": ["100.99.250.145"],
                          "wap1.nokia.com": ["192.168.1.47"]}

        :param info_type: List of information to be logged, None by default
        :param timeout: int or string of float, time in seconds or None
        :return: string value for single info; dict {'info_name': 'info_value'} for multiple infos
        """
        if info_type:
            info_type = info_type if isinstance(info_type, list) else [info_type]
            info_type = [str(attr).lower() for attr in info_type]
            info_type = None if 'all' in info_type else info_type

        self.logger.debug("executing get_info with parameters {}".format(info_type))
        if info_type and 'ip' in info_type:
            self.logger.warning("legacy ue 'ip' info will be deprecated, use 'ips' instead")
            ip_info = {'ip': self._get_ue_ip()}
            # Remove 'ip' from info_type, it is deprecated in taf.ue.proxy
            info_type.remove('ip')
            if len(info_type):
                response = self.ue_pc.get_ue_info(ue_id=self.ue_id, ue_attributes=info_type)
                response.update(ip_info)
            else:
                response = ip_info
        else:
            response = self.ue_pc.get_ue_info(ue_id=self.ue_id, ue_attributes=info_type)

        self.logger.debug(json.dumps(response, sort_keys=False, indent=4))
        return response

    @add_interface_trace
    def reboot(self, timeout=120):
        """
        Reboot UE and wait until it is fully functional.

        :param timeout - waiting time in seconds for ue after reboot
        :return: None
        """
        self.logger.debug("Executing reboot ue")
        return self.ue_pc.reboot_ue(ue_id=self.ue_id, timeout=timeout)

    @add_interface_trace
    def change_deployment_mode(self, deployment_mode):
        self.ue_pc.change_deployment_mode(ue_id=self.ue_id, deployment_mode=deployment_mode)

    def enable_elg_logging(self, enable=True):
        self.ue_pc.enable_elg_logging(ue_id=self.ue_id, enable=enable)

    def is_elg_enabled(self):
        return self.ue_pc.is_elg_enabled(ue_id=self.ue_id)

    @add_interface_trace
    def get_deployment_mode(self):
        """
        Detect deployment mode
        :return: deployment mode
        :rtype: str
        """
        return self.ue_pc.get_deployment_mode(ue_id=self.ue_id)

    @add_interface_trace
    def create_default_pdn(self):
        result = self.ue_pc.create_default_pdn(ue_id=self.ue_id)
        self.ue_ip = self._get_ue_ip()
        return result

    @staticmethod
    def _convert_pdn_to_json_string(pdn):
        import json
        return json.dumps(pdn)

    @add_interface_trace
    def connect_additional_pdn(self, pdn):
        """
        Establish additional default bearer.

        :param str pdn: PDN logical name (what type of network we want: internet, mms, ...)
        :return: UE ip from additional PDN
        """
        pdn_from_config = self.pdns.get(pdn)
        if pdn_from_config is None:
            raise KeyError('PDN "{}" not found in configuration'.format(pdn))
        pdn_config = self._convert_pdn_to_json_string(pdn_from_config)
        result = self.ue_pc.connect_additional_pdn(ue_id=self.ue_id, pdn_name=pdn, pdn_config=pdn_config)
        self.current_pdn_name = pdn
        self.ue_ip = self._get_ue_ip()
        return result

    @add_interface_trace
    def disconnect_additional_pdn(self, pdn):
        """
        Release additional default bearer.

        :param str pdn: PDN logical name (what type of network we want: internet, mms, ...)
        :return: None
        """
        try:
            pdn_from_config = self.pdns.get(pdn)
            apn_name = pdn_from_config['apn']
        except (KeyError, TypeError, AttributeError):
            raise KeyError('PDN "{}" not found in configuration'.format(pdn))
        self.ue_pc.disconnect_additional_pdn(ue_id=self.ue_id, apn_name=apn_name)
        self.current_pdn_name = self.default_pdn_name
        self.ue_ip = self._get_ue_ip()

    def switch_to_pdu_session(self, pdn_name):
        self._switch_to_pdu_session(pdn_name)

    def _switch_to_pdu_session(self, pdn_name):
        self.ue_pc.switch_to_pdu_session(ue_id=self.ue_id, pdn_name=pdn_name)
        self.current_pdn_name = pdn_name
        self.ue_ip = self._get_ue_ip()

    @add_interface_trace
    def _create_data_transfer(self, name, dt_definition):
        """
        Creating IperfDataTransfer object.

        :param name: name to be assigned to starting transfer. You must use it later on to reference given transfer.
        :param dt_definition: object of DataTransferDefinition that encapsulates all needed parameters.
        :return: IperfDataTransfer instance
        """

        pdn_name = self._get_pdn_from_bearer(dt_definition.bearer)
        if pdn_name:
            self._switch_to_pdu_session(pdn_name)
            self.logger.info("switch to pdu session {}".format(pdn_name))

        if not self.ue_ip:
            raise NoIpError("MediaTek UE didn't get any IP address for data transfer.")
        if dt_definition.direction == "dl":
            return IperfDownLinkDataTransfer(name, dt_definition, self._configuration, self)

        if dt_definition.direction == "ul":
            return IperfUpLinkDataTransfer(name, dt_definition, self._configuration, self)

    def _get_pdn_from_bearer(self, bearer):
        pdn_name = bearer.bearer_identification["pdn"]
        if self.pdns:
            self.logger.info("pdns: {}".format(self.pdns))
            for pdn in self.pdns:
                if pdn == pdn_name:
                    return pdn_name
        self.logger.info("pdn_name {} not found in {}".format(pdn_name, self.pdns))
        return None

    def get_data_transfer_raw_data(self, dt_name, output_file=None):
        """Get all raw statistics of data transfer final result"""
        data_transfer = self._get_dt(dt_name)
        stats = data_transfer.get_data_transfer_raw_data(output_file)
        return stats

    def _get_dt(self, dt_name):
        """
        Find data transfer from dt aliases registry or raises exception.

        :param dt_name: alias of data transfer to find
        :return: dt object if found
        """
        if dt_name not in aliases_registry():
            expected_preceding_call = "Start Data Transfer  {} ...".format(dt_name)
            how_to_fix_info = "  you should precede it with starting data transfer with given alias '{}'".format(expected_preceding_call)
            self.logger.error("UnknownAlias({})".format(how_to_fix_info))
            raise UnknownAlias(how_to_fix_info)
        dt = aliases_registry()[dt_name]
        # aliases registry holds objects of different type, check if alias points to data transfer
        if not isinstance(dt, LteDataTransfer):
            why_wrong_info = "  should be alias of LteDataTransfer object but it points to '{}' object".format(dt.__class__.__name__)
            expected_preceding_call = "Start Data Transfer  DT_alias  ..."
            how_to_fix_info = "  you should use DT_alias given at '{}'".format(expected_preceding_call)
            err_msg = why_wrong_info + "\n" + how_to_fix_info
            self.logger.error("WrongAlias({})".format(err_msg))
            raise WrongAlias(err_msg)
        return dt

    def disable_ue_ul_mimo(self):
        self.ue_pc.disable_ue_ul_mimo(ue_id=self.ue_id)
